int main(void){TaxiWorldAsset world={0};if(taxi_world_asset_load(&world,"outputs/crazy-taxi-native/assets/challenge-worlds/challenge5.ctw"))return 3;TaxiActorEffects s;taxi_actor_effects_cold_init(&s);unsigned char table[16388];FILE*f=fopen("outputs/crazy-taxi-native/assets/driving.ctr","rb");if(!f||fread(table,1,sizeof table,f)!=sizeof table)return 4;fclose(f);TaxiTrig trig;taxi_trig_decode(&trig,table+4,table+8196);int x,y,z,pitch,roll,heading,drift,material,flags,speed,scale,phase,voice,state,action;while(scanf("%d%d%d%d%d%d%d%d%d%d%d%d%d%d%d",&x,&y,&z,&pitch,&roll,&heading,&drift,&material,&flags,&speed,&scale,&phase,&voice,&state,&action)==15){TaxiBodyPoints b;if(taxi_body_points(&b,(TaxiPoint){x,y,z},(uint16_t)pitch,(uint16_t)roll,heading,drift,&trig)<0)return 5;if(material<0||(unsigned)material>=world.nm)return 6;TaxiActorEffectInput i={.material_flags=world.materials[28u*(unsigned)material+20],.actor_flags=(uint8_t)flags,.action2=(uint8_t)action,.voice_25d4=(uint8_t)voice,.speed=speed,.scale=scale,.alternate=0,.phase_e6a=(uint8_t)phase,.state_2630=state,.delta=1,.clock=60};if(taxi_actor_effects_step(&s,&b,i,taxi_world_asset_height,&world)<0)return 2;printf("%u",s.ring);for(unsigned j=0;j<4;j++)printf(" %d",s.timers[j]);for(unsigned g=0;g<2;g++)for(unsigned j=0;j<6;j++)printf(" %d",s.pool.slots[g][j]);for(unsigned j=0;j<648;j++)printf(" %u",((unsigned char*)s.pool.records)[j]);puts("");}taxi_world_asset_free(&world);return 0;}
